const out={};
for (const col of ['C','M']) { wb.getRange('Sheet1!C5').setValue(wb.getRange('Sheet2!'+col+'5').getValue());
 const v=wb.getRange('Sheet1!C6:C31').getValues().flat();
 const miss=[]; for(let i=0;i<26;i++){ const it=String.fromCharCode(65+i); const c=await wb.evaluate('=COUNTIF(Sheet2!'+col+'6:'+col+'1000,"'+it+'")'); if ((c>0?it:'NEW')!==v[i]) miss.push(it);} 
 out[col]={v:v.join(','),miss}; }
out

